/**
 * Test de charge du panel des agents (demande du 01/11 : « faire comme s'il y avait beaucoup de clients et corriger
 * les points faibles »). Trois sortes de clients en même temps, sur une COPIE isolée du panel (jamais celui en ligne,
 * qui tourne sur le serveur du bot de trading) :
 *   - navigation : des utilisateurs qui consultent le panel (menu, accueil, leur projet, chronologie, carte, sécurité)
 *     avec un temps de lecture entre deux pages, comme le rafraîchissement de la page ;
 *   - appareils  : des ordinateurs connectés qui se synchronisent toutes les 5 s (rythme réel de node.js) ;
 *   - connexions : des connexions par mot de passe (calcul scrypt, le plus coûteux).
 * Les comptes et les ordinateurs sont créés au début (setup) par les vraies routes du panel.
 * Lancer : voir k6/README.md (USERS, DEVICES, BASE_URL réglables).
 */
import http from 'k6/http';
import { check, sleep } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:3099';
const USERS = Number(__ENV.USERS || 200);
const DEVICES = Number(__ENV.DEVICES || 100);
const JSON_HEADERS = { 'Content-Type': 'application/json' };

export const options = {
  setupTimeout: '15m', // création des comptes et des ordinateurs (2000 comptes : plusieurs minutes)
  scenarios: {
    navigation: {
      executor: 'ramping-vus',
      exec: 'navigation',
      startVUs: 0,
      stages: [
        { duration: '30s', target: USERS }, // arrivée des utilisateurs
        { duration: '90s', target: USERS }, // tout le monde sur le panel
        { duration: '15s', target: 0 },
      ],
      gracefulRampDown: '10s',
    },
    appareils: {
      executor: 'constant-arrival-rate',
      exec: 'appareils',
      rate: DEVICES, // chaque ordinateur une fois toutes les 5 s
      timeUnit: '5s',
      duration: '2m15s',
      preAllocatedVUs: 50,
      maxVUs: 300,
    },
    connexions: {
      executor: 'constant-arrival-rate',
      exec: 'connexions',
      rate: 3,
      timeUnit: '1s',
      duration: '2m',
      preAllocatedVUs: 10,
      maxVUs: 100,
    },
  },
  thresholds: {
    http_req_failed: ['rate<0.01'],
    checks: ['rate>0.99'],
    'http_req_duration{name:nav}': ['p(95)<500'],
    'http_req_duration{name:overview}': ['p(95)<800'],
    'http_req_duration{name:projet}': ['p(95)<800'],
    'http_req_duration{name:chronologie}': ['p(95)<800'],
    'http_req_duration{name:sync}': ['p(95)<500'],
    'http_req_duration{name:login}': ['p(95)<1500'],
  },
};

// Adresse de client différente par compte (le panel limite les essais par adresse, comme pour de vrais clients).
const ip = (i) => `10.${Math.floor(i / 250) % 250}.${i % 250}.${(i * 7) % 250 + 1}`;

export function setup() {
  const users = [];
  for (let i = 0; i < USERS; i++) {
    const email = `client${i}-${Date.now()}@charge.invalid`, password = `motdepasse-${i}-charge`;
    const res = http.post(`${BASE_URL}/api/auth/signup`, JSON.stringify({ email, password, name: `Client ${i}` }), { headers: { ...JSON_HEADERS, 'X-Real-IP': ip(i) } });
    check(res, { 'inscription 200': (r) => r.status === 200 });
    const c = res.cookies.ag_session;
    users.push({ email, password, cookie: c && c.length ? `ag_session=${c[0].value}` : '', ip: ip(i) });
  }
  const devices = [];
  for (let i = 0; i < Math.min(DEVICES, users.length); i++) {
    const u = users[i];
    const code = http.post(`${BASE_URL}/api/nodes/code`, '{}', { headers: { ...JSON_HEADERS, Cookie: u.cookie, 'X-Real-IP': u.ip } }).json('code');
    const en = http.post(`${BASE_URL}/api/node/enroll`, JSON.stringify({ code, name: `PC-${i}`, info: { os: 'Windows', node: 'v24', claude: '2.x' },
      project: { name: `Projet ${i}`, dir: `C:/clients/${i}/projet`, testCmd: 'npm test' } }), { headers: { ...JSON_HEADERS, 'X-Real-IP': ip(10000 + i) } });
    check(en, { 'ordinateur connecté 200': (r) => r.status === 200 });
    const project = en.json('project.id');
    u.project = project;
    devices.push({ token: en.json('token'), project });
  }
  return { users, devices, start: new Date().toISOString() };
}

// Un utilisateur qui consulte le panel, puis lit quelques secondes.
export function navigation(data) {
  const u = data.users[(__VU - 1) % data.users.length];
  const params = (name) => ({ headers: { Cookie: u.cookie, 'X-Real-IP': u.ip }, tags: { name } });
  const reqs = [['GET', `${BASE_URL}/api/nav`, null, params('nav')], ['GET', `${BASE_URL}/api/overview`, null, params('overview')], ['GET', `${BASE_URL}/api/me/security`, null, params('securite')]];
  if (u.project) {
    reqs.push(['GET', `${BASE_URL}/api/projects/${u.project}`, null, params('projet')],
      ['GET', `${BASE_URL}/api/projects/${u.project}/timeline?days=1`, null, params('chronologie')],
      ['GET', `${BASE_URL}/api/projects/${u.project}/graph`, null, params('carte')]);
  }
  const res = http.batch(reqs);
  check(res, { 'pages 200': (rs) => rs.every((r) => r.status === 200) });
  sleep(3 + Math.random() * 2);
}

// Un ordinateur connecté qui se synchronise (avec de temps en temps un passage d'agent à envoyer). Comme le vrai
// programme (node.js), il renvoie à chaque fois l'état des passages, qui ne change que lorsqu'un agent a tourné.
export function appareils(data) {
  const d = data.devices[Math.floor(Math.random() * data.devices.length)];
  const history = Math.random() < 0.1 ? [{ at: new Date().toISOString(), agent: 'scout', source: 'horaire', status: 'ok', summary: 'passage de charge', seconds: 12 }] : [];
  const lastAt = history.length ? history[0].at : data.start;
  const body = { info: { os: 'Windows', node: 'v24', claude: '2.x' }, status: { current: null }, projects: { [d.project]: { runs: { scout: { lastAt, lastStatus: 'ok' } }, history, notes: [], files: {} } } };
  const res = http.post(`${BASE_URL}/api/node/sync`, JSON.stringify(body), { headers: { ...JSON_HEADERS, Authorization: `Bearer ${d.token}` }, tags: { name: 'sync' } });
  check(res, { 'synchronisation 200': (r) => r.status === 200 });
}

// Une connexion par mot de passe.
export function connexions(data) {
  const i = Math.floor(Math.random() * data.users.length), u = data.users[i];
  const res = http.post(`${BASE_URL}/api/auth/login`, JSON.stringify({ email: u.email, password: u.password }), { headers: { ...JSON_HEADERS, 'X-Real-IP': ip(20000 + __ITER * 50 + __VU) }, tags: { name: 'login' } });
  check(res, { 'connexion 200': (r) => r.status === 200 });
}
